import React from 'react';
import Styled from './EmptyTable.styles';

const EmptyTable = ({
  span,
  message,
}: {
  span: number | undefined;
  message: React.ReactNode;
}): JSX.Element => (
  <tr>
    <td colSpan={span}>
      <Styled.LoadingContainer>{message}</Styled.LoadingContainer>
    </td>
  </tr>
);

export default EmptyTable;
